{"code": "note_finding = lambda msg, implication=None: _contract['findings'].append({'finding': msg, 'implication': implication})

# Check for any obvious issues
if sales_df['revenue'].isna().sum() > 0:
    note_finding('Missing revenue values detected', 'Must exclude or impute them')
else:
    note_finding('All revenue values are present', 'No imputation needed')

# Check for duplicate orders
if sales_df['order_id'].duplicated().any():
    note_finding('Duplicate order IDs found', 'Must deduplicate to avoid double-counting')
else:
    note_finding('No duplicate order IDs', 'Data is clean on order_id')

# Check if 'converted' is binary and consistent
if sorted(sales_df['converted'].unique()) != [0, 1]:
    note_finding('Converted is not binary (0/1)', 'This may indicate data quality issue')
else:
    note_finding('Converted is binary (0/1)', 'Valid for analysis')

# Check status: only completed and refunded
if set(sales_df['status'].unique()) != {'completed', 'refunded'}:
    note_finding('Unexpected status values', 'May affect revenue and conversion logic')
else:
    note_finding('Status values are as expected', 'No data quality issue')

# Check for imbalance in channel distribution
channel_counts = sales_df['channel'].value_counts()
if channel_counts.min() / channel_counts.max() < 0.5:
    note_finding('Channel distribution is imbalanced', 'May bias comparison; need to adjust for this')
else:
    note_finding('Channel distribution is balanced', 'No need for adjustment')

# Report findings
_contract['findings']"}
